/** 论文字数统计：中文按字，英文按词（粗略） */
export function countThesisWords(text: string): number {
  const t = text.trim();
  if (!t) return 0;
  const cn = (t.match(/[\u4e00-\u9fff]/g) || []).length;
  const withoutCn = t.replace(/[\u4e00-\u9fff]/g, " ");
  const enWords = withoutCn
    .trim()
    .split(/\s+/)
    .filter((w) => /[a-zA-Z]/.test(w)).length;
  return cn + enWords;
}

export function truncatePreview(text: string, max = 6000): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n\n…（仅预览前 ${max} 字）`;
}

import React from "react";
import {
  Card,
  Upload,
  Typography,
  Space,
  Button,
  Switch,
  Select,
  Row,
  Col
} from "antd";
import { InboxOutlined, FileTextOutlined } from "@ant-design/icons";
import type { UploadProps } from "antd";
import GooeySplitButton from "./GooeySplitButton";
import { countThesisWords, truncatePreview } from "../utils/textStats";

const { Dragger } = Upload;

type PreviewState = {
  name: string;
  text: string;
  wordCount: number;
  error?: string;
};

const UploadCard: React.FC = () => {
  const [preview, setPreview] = React.useState<PreviewState | null>(null);

  const beforeUpload: UploadProps["beforeUpload"] = (file) => {
    const name = file.name || "未命名";
    const ext = name.split(".").pop()?.toLowerCase() ?? "";
    const textLike =
      /^(txt|md|markdown|json|csv)$/i.test(ext) ||
      file.type.startsWith("text/") ||
      file.type === "application/json";

    if (!textLike) {
      setPreview({
        name,
        text: "",
        wordCount: 0,
        error:
          "当前示例仅支持预览 .txt / .md 等纯文本。PDF / Word 需服务端解析后再接入预览。"
      });
      return Upload.LIST_IGNORE;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const raw = String(e.target?.result ?? "");
      const wordCount = countThesisWords(raw);
      setPreview({
        name,
        text: truncatePreview(raw),
        wordCount
      });
    };
    reader.onerror = () => {
      setPreview({
        name,
        text: "",
        wordCount: 0,
        error: "文件读取失败，请重试或换用 UTF-8 编码的文本文件。"
      });
    };
    reader.readAsText(file, "UTF-8");
    return Upload.LIST_IGNORE;
  };

  return (
    <Card styles={{ body: { overflow: "visible" } }}>
      <Space direction="vertical" style={{ width: "100%" }} size={16}>
        <Typography.Title level={5} style={{ margin: 0 }}>
          上传论文文件
        </Typography.Title>
        <Typography.Text type="secondary">
          支持 PDF / Word / Markdown，系统会自动按段落拆分并统计字数（当前为前端示例，不会真实上传）。
        </Typography.Text>
        <Dragger
          multiple={false}
          showUploadList={false}
          beforeUpload={beforeUpload}
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined />
          </p>
          <p className="ant-upload-text">点击或拖拽文件到此区域上传</p>
          <p className="ant-upload-hint">文件不会离开本地，仅用于界面预览示意。</p>
        </Dragger>

        <Row gutter={[16, 16]} align="bottom">
          <Col xs={24} lg={16}>
            <Space size={16} wrap align="center">
              <Space>
                <Typography.Text>自动分段预览</Typography.Text>
                <Switch defaultChecked />
              </Space>
              <Space>
                <Typography.Text>论文语言</Typography.Text>
                <Select
                  defaultValue="zh"
                  options={[
                    { label: "中文", value: "zh" },
                    { label: "英文", value: "en" }
                  ]}
                  style={{ width: 100 }}
                />
              </Space>
              <Space size={10} align="center" wrap>
                <Button type="link" size="small">
                  查看示例论文
                </Button>
                <GooeySplitButton />
              </Space>
            </Space>
          </Col>
          <Col xs={24} lg={8}>
            <div className="upload-preview-box">
              <div className="upload-preview-box__head">
                <FileTextOutlined className="upload-preview-box__icon" />
                <Typography.Text strong>内容预览</Typography.Text>
              </div>
              {!preview && (
                <Typography.Text type="secondary" className="upload-preview-box__placeholder">
                  上传文本类文件后，将在此显示摘要与字数统计。
                </Typography.Text>
              )}
              {preview && (
                <>
                  <div className="upload-preview-box__meta">
                    <Typography.Text ellipsis title={preview.name}>
                      {preview.name}
                    </Typography.Text>
                    <Typography.Text type="secondary">
                      {preview.error
                        ? "—"
                        : `约 ${preview.wordCount.toLocaleString()} 字`}
                    </Typography.Text>
                  </div>
                  {preview.error ? (
                    <Typography.Text type="danger" className="upload-preview-box__error">
                      {preview.error}
                    </Typography.Text>
                  ) : (
                    <pre className="upload-preview-box__body">{preview.text || "（空文件）"}</pre>
                  )}
                </>
              )}
            </div>
          </Col>
        </Row>
      </Space>
    </Card>
  );
};

export default UploadCard;

