function getNextParagraphIndex(
  list: Array<{ index: number }>,
  afterIdx: number
): number | null {
  const sorted = [...list].sort((a, b) => a.index - b.index);
  const i = sorted.findIndex((p) => p.index === afterIdx);
  if (i < 0 || i >= sorted.length - 1) return null;
  return sorted[i + 1].index;
}

