def ensure_leading_section_heading_line(original: str, reduced: str) -> str:
    """
    若原文段首为小节标题行，而模型输出首段非标题（常见为直接写正文），则补回原文标题行。
    若模型已输出小节标题（含同编号如 1.3），则不覆盖。
    """
    if not original.strip() or not reduced.strip():
        return reduced
    o_lines = original.splitlines()
    if not o_lines:
        return reduced
    h = o_lines[0].strip()
    if not is_chapter_heading_line(h):
        return reduced
    r_lines = reduced.splitlines()
    fi = 0
    while fi < len(r_lines) and not r_lines[fi].strip():
        fi += 1
    if fi >= len(r_lines):
        return h + "\n" + reduced
    r_first = r_lines[fi].strip()
    if r_first == h:
        return reduced
    if is_chapter_heading_line(r_first):
        return reduced
    num_h = re.match(r"^(\d+(?:\.\d+)*)", h)
    num_r = re.match(r"^(\d+(?:\.\d+)*)", r_first)
    if num_h and num_r and num_h.group(1) == num_r.group(1):
        return reduced
    return h + "\n" + reduced


def finalize_reduce_text(original: str, reduced: str) -> str:
    """降 AIGC 最终后处理：补回段首标题 + 统一标题后空行。"""
    if not reduced:
        return reduced
    x = ensure_leading_section_heading_line(original, reduced)
    return normalize_heading_spacing_after_model(original, x)


